"""Build a review gallery from the native Pen export registry."""
import html,json,zipfile
from pathlib import Path
root=Path(__file__).resolve().parent
data=json.loads((root/'templates.json').read_text(encoding='utf8'))
cards=[]
for t in data['templates']:
    esc=html.escape
    path='exports/'+t['id']+'.png'
    cards.append(f'''<article class="template" data-format="{esc(t['format'])}" id="{esc(t['id'])}"><div class="canvas"><a href="{path}" target="_blank" rel="noopener"><img src="{path}" alt="{esc(t['title'])}" loading="lazy" width="{t['width']}" height="{t['height']}"></a></div><div class="caption"><div class="spec">{t['width']} × {t['height']} / {esc(t.get('language','EN'))}</div><h2>{esc(t['title'])}</h2><p>{esc(t['purpose'])}</p><a href="{path}" download>Download PNG ↗</a></div></article>''')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GMD / Social system</title><link rel="stylesheet" href="../tokens.css"><style>
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.5 var(--font-body)}a{color:var(--nile)}header,main,footer{max-width:1440px;margin:auto;padding:32px}header{padding-top:48px;border-bottom:1px solid var(--ink)}.label,.spec{font:13px/1.5 var(--font-label);text-transform:uppercase}.label{color:var(--nile)}h1{font:clamp(44px,6vw,88px)/1 var(--font-display);font-weight:400;max-width:900px;margin:24px 0}header p{max-width:800px}.links{display:flex;gap:16px;flex-wrap:wrap}.links a{padding:10px 16px;border:1px solid var(--ink);text-decoration:none;box-shadow:3px 3px 0 var(--ink)}.links a:first-child{background:var(--pink);color:var(--ink)}.filters{display:flex;gap:0;flex-wrap:wrap;margin-bottom:32px}button{background:var(--surface);color:var(--ink);padding:12px 18px;border:1px solid var(--ink);font:13px var(--font-label);cursor:pointer}button[aria-pressed=true]{background:var(--nile);color:var(--paper)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:32px}.template{background:var(--surface);border:1px solid var(--ink);box-shadow:5px 5px 0 var(--ink)}.template[hidden]{display:none}.canvas{background:var(--warm);padding:24px;display:flex;align-items:center;justify-content:center;height:520px}.template[data-format=banner] .canvas{height:240px}.template[data-format=story] .canvas{height:640px}.template[data-format=link] .canvas{height:350px}.canvas a{display:flex;height:100%;width:100%;align-items:center;justify-content:center}.canvas img{display:block;max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain;box-shadow:0 0 0 1px var(--ink)}.caption{padding:24px;border-top:1px solid var(--ink)}h2{font:32px/1.1 var(--font-display);font-weight:400;margin:12px 0}.caption p{max-width:560px}.ref{margin-top:56px;padding:32px 0;border-top:1px solid var(--ink)}.ref img{max-width:100%;height:auto;display:block}.ref h2{font-size:40px}.rules{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px}.rules h3{font:24px var(--font-display)}footer{border-top:1px solid var(--ink);color:var(--muted)}a:focus-visible,button:focus-visible{outline:3px solid var(--nile);outline-offset:6px}@media(max-width:720px){header,main,footer{padding:24px}.grid,.rules{grid-template-columns:1fr}.canvas{height:450px;padding:16px}h1{font-size:48px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style><header><a href="../index.html">← GMD design system</a><div class="label">GMD / Social composition library</div><h1>Give the story<br>room to speak.</h1><p>A new social family built from the Tavus brand kit's use of space, contrast and one dominant visual. Native editable GMD artboards carry the shared paper, ink and Nile foundation.</p><div class="links"><a href="gmd-social-templates.zip" download>Download template exports</a><a href="SPEC.md">Composition and format rules</a><a href="../unified-boards.html">Unified Pen boards</a></div></header><main><nav class="filters" aria-label="Filter template formats"><button type="button" data-filter="all" aria-pressed="true">ALL</button><button type="button" data-filter="banner" aria-pressed="false">BANNERS</button><button type="button" data-filter="post" aria-pressed="false">POSTS</button><button type="button" data-filter="story" aria-pressed="false">STORIES</button><button type="button" data-filter="link" aria-pressed="false">LINK CARDS</button></nav><div class="grid">'''+''.join(cards)+'''</div><section class="ref"><div class="label">Source / Tavus Brand Lite</div><h2>The reference is a composition language.</h2><div class="rules"><div><h3>Space and identity</h3><p>Large blank areas and a clear signature replace crowded website-like panels.</p></div><div><h3>One dominant visual</h3><p>Texture, media or geometry takes the lead. Supporting copy stays brief and legible.</p></div><div><h3>Adapt by format</h3><p>Recompose banners, covers and stories individually. Keep cultural motifs distinct and functional text outside their detail.</p></div></div><p>The kit supplies flattened banner references. GMD templates are newly authored native Pen layouts; the vendor's logo and 3D symbol are not part of GMD artwork.</p><a href="../../../reviews/brand-kit-social-findings.md">Brand-kit inspection notes</a></section></main><footer>GMD v0.05 / Social review specimens. Export sizes are GMD working presets, not a claim of current platform requirements. Sample imagery is for layout review.</footer><script>for(const b of document.querySelectorAll('[data-filter]'))b.addEventListener('click',()=>{for(const o of document.querySelectorAll('[data-filter]'))o.setAttribute('aria-pressed',String(o===b));for(const a of document.querySelectorAll('[data-format]'))a.hidden=b.dataset.filter!=='all'&&a.dataset.format!==b.dataset.filter;});</script></html>'''
(root/'index.html').write_text(page,encoding='utf8')
with zipfile.ZipFile(root/'gmd-social-templates.zip','w',zipfile.ZIP_DEFLATED) as z:
    for t in data['templates']:
        p=root/'exports'/(t['id']+'.png');z.write(p,'exports/'+p.name)
    for name in ('templates.json','SPEC.md'):
        if (root/name).exists():z.write(root/name,name)
print('Built gallery and bundle for',len(data['templates']),'templates')
